arguments.command:
cd /tmp/vally-eval-trial-8qrWvl
mkdir -p tests/CheckoutPricing.UnitTests/Checkout
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier
{
    Gold,
}

public sealed record CalculatePayableTotalQuery(CustomerTier Tier, decimal Subtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalQuery query) => query.Subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/GoldCustomerDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class GoldCustomerDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var handler = new CalculatePayableTotalHandler();

        var total = handler.Handle(new CalculatePayableTotalQuery(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -v "^\s*$" | tail -20

